/* Calculates the measures and periods of one product in the markets the user chooses when the script runs. */
SET UPDATECALC OFF;
SET RUNTIMESUBVARS
{
    CalcProduct = "100-10"
    <RTSV_HINT><svLaunch>
        <description>Product to calculate</description>
        <type>member</type>
        <dimension>Product</dimension>
        <allowMissing>false</allowMissing>
        <choice>single</choice>
    </svLaunch></RTSV_HINT>;
    CalcMarkets = "New York"
    <RTSV_HINT><svLaunch>
        <description>Markets to calculate</description>
        <type>member</type>
        <dimension>Market</dimension>
        <allowMissing>false</allowMissing>
        <choice>multiple</choice>
    </svLaunch></RTSV_HINT>;
};

FIX(&CalcProduct, &CalcMarkets)
    CALC DIM(Measures, Year);
ENDFIX
